@firm_staff_required
def client_edit(request, client_id: int):
    client = get_object_or_404(Client, pk=client_id)
    if request.user.role not in {Role.FIRM_ADMIN, Role.ATTORNEY}:
        raise PermissionDenied("Only attorneys or firm admins can edit clients.")
    if request.user.role != Role.FIRM_ADMIN and not matters_visible_to(request.user).filter(client=client).exists():
        raise PermissionDenied("You do not have access to this client.")
    if request.method == "POST":
        form = ClientForm(request.POST, instance=client)
